import sys,math
sys.path.insert(0,'/tmp/kh/gen')
from h import *
from sidport import saxton,psiF
from dripport import *
from lib import SOIL
TEX={'S01':(45,20),'S02':(88,4),'S03':(92,3),'S04':(82,6),'S05':(65,10),'S06':(40,20),'S07':(20,15),'S08':(55,30),'S09':(30,35),'S10':(10,35)}
def W(t): return '\\par\\noindent where '+t+'\n\n'
def E(eq,wh,lab=''): return '\\begin{equation}'+(('\\boxed{'+eq+'}') if len(eq)<170 else eq)+(('\\label{%s}'%lab) if lab else '')+'\\end{equation}\n'+W(wh)
def sh(sid):
    sd,cl=TEX[sid];s=saxton(sd/100,cl/100,1.5);return s
def D_(sid,kind='inline',q=2.,Se=.5,Sl=1.5,LL=100,H0=10,D=16,Zn=9,dep=25,Rmax=60,E0=2.5,t=None,fT=.5):
    s=sh(sid);return drip(kind,q,Se,Sl,LL,H0,D,Zn,s['ks']*24/10,0,s['fc'],s['wp'],fT,dep,Rmax,E0,t)
b=''
b+=sec('Drip irrigation: what the layer does')
b+=P(r"The drip layer designs the system from the emitter to the root zone. From the soil of the field it takes the water that must be applied (the net depth $Z_n$ to the trigger), the water-holding properties ($\theta_{33}$, $\theta_{1500}$, $K_s$) and the root depth; from the user it takes the emitter, the spacing of emitters and laterals, the length and diameter of the lateral, the inlet pressure and the depth of placement. It returns the emission uniformity, the head lost along the lateral, the wetted bulb under the average emitter, the run time, and the fate of every litre: stored in the root zone, deep percolation, or evaporation from the wet surface.")
b+=sec('Types of emitters and their parameters')
b+=P(r"The application offers six emitters. They differ in the variation of the discharge from one emitter to another (the manufacturing coefficient of variation $c_v$), in the sensitivity of the discharge to pressure (the exponent $x$), in the number of emitters that a plant is watered by ($n_e$) and, for the pressure-compensating drippers, in the minimum head $H_{\min}$ below which compensation fails.")
rows=[[d['l'],'%.2f'%d['cv'],'%.2f'%d['x'],d['ne'],'%.1f'%d['Hmin'],'%.1f'%d['q'],'%.2f'%d['Se'],'%.1f'%d['D']] for d in DK.values()]
b+=tabl(['Emitter','$c_v$','$x$','$n_e$','$H_{\\min}$ (m)','default $q$ (L/h)','default $S_e$ (m)','inside $D$ (mm)'],rows,'Emitters of the drip layer.','lrrrrrrr')
b+=P(r"\textbf{Online emitters} are punched into a polyethylene tube; they are cheap and can be placed where the plants are, but they vary most ($c_v=0.07$). \textbf{Inline emitters} are welded in the tube at a fixed spacing and vary less ($c_v=0.04$). \textbf{Drip tape} is a thin-walled tube with a continuous labyrinth; it is used for one season on vegetables at close spacing (0.2 m), and because the wall is thin the discharge is sensitive to pressure ($x=0.6$) and each plant is watered by two emitters. The three \textbf{pressure-compensating} drippers (PC AS, anti-siphon; PC LCNL, low-pressure non-leakage; PC HCNL, high-pressure non-leakage) keep the discharge constant ($x=0$) above a minimum head, which is why they are used on slopes and in long laterals. The non-leakage types shut off below 0.15 or 0.3 m of head, which prevents draining of the lateral at the end of the run. The lateral pipes of the library are 16 mm (inside 13.7 mm, wall 0.95 mm, working pressure 4.5 bar) and 20 mm (inside 17.5 mm).")
b+=sec('Where to place the emitter')
b+=P(r"The emitter can lie on the surface or be buried at 15, 25, 45 or 55 cm. Burying reduces the evaporation from the wet surface and keeps the water in the root zone; but if the emitter is deeper than the roots, or the soil is coarse, the water leaves the root zone before the roots can take it. The application computes, for every placement, the water that passes below the maximum rooting depth ($R_{max}$) as deep percolation, and the water that reaches the surface as evaporation.")
b+=sec('Governing equations')
b+=P(r"\textbf{The emitter.} The discharge depends on the head $H$ at the emitter as a power law,",
 E(r"q=q_0\left(\frac{H}{H_0}\right)^{x},",r"$q$ is the discharge of the emitter (L\,h$^{-1}$), $q_0$ the nominal discharge at the nominal head $H_0$ (m), $H$ the head at the emitter (m) and $x$ the emitter exponent ($x=0.5$ for a fully turbulent orifice, 1 for a laminar one, 0 for a perfect compensator). A pressure-compensating emitter keeps $q=q_0[1+0.04(H-H_0)/H_0]$ for $H\ge H_{\min}$ and falls as $q_0(H/H_{\min})^{0.5}$ below it.",'eq:d-em'),
 r"\textbf{The lateral.} The head falls along the lateral because of friction. For the segment between emitters $j$ and $j+1$, of length $S_e$ and carrying the flow still to be delivered downstream, $Q_j=\sum_{i>j}q_i$, the Hazen--Williams loss is",
 E(r"\Delta H_j=\frac{10.67\,S_e\,Q_j^{1.852}}{C^{1.852}D^{4.871}},\qquad H_{j+1}=H_j-\Delta H_j,",r"$\Delta H_j$ is the head lost in the segment (m), $S_e$ the emitter spacing (m), $Q_j$ the flow in the segment (m$^3$\,s$^{-1}$; the sum of the discharges, in L\,h$^{-1}$, of the emitters beyond $j$ divided by $3.6\times10^{6}$), $C$ the Hazen--Williams coefficient (140 in the application) and $D$ the inside diameter (m).",'eq:d-hw'),
 r"The discharges depend on the heads and the heads on the discharges, so the application iterates (four undamped passes, then under-relaxed with a factor 0.5, until the discharges change by less than $10^{-7}q$, at most 500 passes). The result is the head and the discharge at every emitter. A lateral is outside the usual design limit when the head lost exceeds 20 per cent of the inlet head: $h_f/H_0>0.2$.",
 r"\textbf{Uniformity.} The coefficient of variation of the discharge combines the manufacturing variation and the variation due to pressure,",
 E(r"\sigma_q=\sqrt{c_v^2+\sigma_P^2},\quad\sigma_P^2=\frac{1}{N+1}\sum_j\left(\frac{q_j}{\bar q}-1\right)^2,\quad E_u=\min\left\{1,\ \left(1-\frac{1.27\,c_v}{\sqrt{n_e}}\right)\frac{q_{\min}}{\bar q}\right\},",r"$\sigma_q$ is the total coefficient of variation of the discharge, $c_v$ the manufacturing coefficient, $\sigma_P$ that due to the pressure, $q_j$ the discharge of emitter $j$, $\bar q$ the mean discharge (L\,h$^{-1}$), $N+1$ the number of emitters on the lateral, $E_u$ the emission uniformity (limited to the range 0.3 to 1), $n_e$ the number of emitters per plant and $q_{\min}$ the smallest discharge on the lateral.",'eq:d-eu'),
 r"The lateral carries $Q=N\bar q/3600$ L\,s$^{-1}$.")
rows=[]
for D in (13.7,16,17.5,20):
    for kind,LL in (('inline',100),('inline',200),('pcas',200)):
        l=latprofile(kind,2,.5,LL,10,D);rows.append([DK[kind]['l'],LL,D,'%.2f'%l['hf'],'%.1f'%(100*l['hfFrac']),'%.3f'%l['qmin'],'%.3f'%l['qa'],'%.1f'%(100*l['Eu'])])
b+=tabl(['Emitter','$L$ (m)','$D$ (mm)','$h_f$ (m)','$h_f/H_0$ (\\%)','$q_{\\min}$ (L/h)','$\\bar q$ (L/h)','$E_u$ (\\%)'],rows,'Laterals with emitters of 2 L/h at 0.5 m spacing and 10 m inlet head: head loss and uniformity from the iteration.','lrrrrrrr')
l=latprofile('inline',2,.5,100,10,16)
b+=ex(r"An inline-emitter lateral ($q_0=2$ L\,h$^{-1}$, $S_e=0.5$ m, $L=100$ m, $D=16$ mm, $H_0=10$ m, $x=0.5$, $c_v=0.04$) is run in the application. Report the number of emitters, the head lost, the extreme and mean discharges, $E_u$ and the flow.",
 r"$N=L/S_e=200$ intervals, i.e.\ 201 emitters \ans At the inlet the segment carries the discharge of the 200 emitters beyond: $Q\approx200\times2/3.6\times10^6=1.11\times10^{-4}$ m$^3$\,s$^{-1}$, $\Delta H=10.67(0.5)(1.11\times10^{-4})^{1.852}/(140^{1.852}\times0.016^{4.871})=%.4f$ m \ans Adding the losses of all segments with the discharges updated by Eq.~(\ref{eq:d-em}) gives, after convergence, $h_f=%.2f$ m, so the last emitter has $H=%.2f$ m, i.e.\ $h_f/H_0=%.1f$ per cent (within the 20 per cent limit) \ans $q_{\min}=%.3f$ L\,h$^{-1}$ (last emitter), $\bar q=%.3f$ L\,h$^{-1}$ \ans $\sigma_P$ and the manufacturing variation give $\sigma_q=%.4f$ \ans $E_u=(1-1.27\times0.04/\sqrt1)(%.3f/%.3f)=%.3f$, that is %.1f per cent \ans Flow $Q=201\times%.3f/3600=%.3f$ L\,s$^{-1}$ \ans"%(10.67*.5*(200*2/3.6e6)**1.852/(140**1.852*.016**4.871),l['hf'],l['Hend'],100*l['hfFrac'],l['qmin'],l['qa'],l['sd'],l['qmin'],l['qa'],l['Eu'],100*l['Eu'],l['qa'],201*l['qa']/3600),'Head loss and uniformity of a lateral')
b+=sec('The wetted bulb')
b+=P(r"Around a buried or surface emitter the water spreads as a body of revolution. The application describes it as a half-ellipsoid below the emitter (radius $r$ at the emitter depth, vertical semi-axis $a\,r$) and a short one above it (vertical semi-axis $u\,r$, $u=0.6$). The width of the body at depth $z$ is",
 E(r"\rho(z)=r\sqrt{1-\left(\frac{z-z_d}{a\,r}\right)^2}\ \ (z\ge z_d),\qquad \rho(z)=r\sqrt{1-\left(\frac{z_d-z}{u\,r}\right)^2}\ \ (z<z_d),",r"$\rho(z)$ is the radius of the wet body at depth $z$ (mm), $z_d$ the depth of the emitter (mm), $r$ the radius at emitter depth (mm), $a$ the aspect ratio (depth below the emitter over radius) and $u=0.6$ the same ratio above.",'eq:d-bulb'),
 r"The volume of soil that holds the water of one emitter is $V_w=V/\Delta\theta$, where $V$ is the volume applied and $\Delta\theta=\max\{0.03,\ f_T(\theta_{33}-\theta_{1500})\}$ is the water that the soil takes up between the trigger and field capacity; the radius $r$ is the one at which the volume of the body, $\int\pi\rho^2dz$ (or $\int2\rho\,dz$ for a line source), equals $V_w$. The shape depends on the soil through the aspect ratio, which expresses the competition of gravity and capillarity:",
 E(r"a=\mathrm{clip}\left\{\left[0.7+1.6\left(\frac{K_s}{K_s+15}\right)^{1.1}\right]\sqrt{\mathrm{clip}\!\left(\frac{2}{q};\,0.7,\,1.4\right)};\ 0.75,\,2.4\right\},",r"$a$ is the aspect ratio of the bulb, $K_s$ the saturated conductivity in cm\,d$^{-1}$ ($=2.4\times K_s$ in mm\,h$^{-1}$) and $q$ the discharge of the emitter (L\,h$^{-1}$); coarse soils give a narrow, deep bulb ($a$ large), fine soils a wide, shallow one, and a larger discharge spreads the water more.",'eq:d-asp'),
 r"When the emitter spacing is less than 0.34 m, or the bulbs of neighbouring emitters touch ($2r>S_e$ with $S_e<1.2$ m), the emitters form a continuous wet strip and the body is treated as a line source with the volume per metre $V/S_e$.",
 r"\textbf{Fate of the water.} Of the volume $V_i$ applied by one emitter, the part of the body below the maximum rooting depth $R_m$ is deep percolation, a part $e=\min\{0.5V_i,\ A_{s}E_0\cdot2\}$ evaporates from the wet surface of area $A_s$ ($E_0$ is the surface evaporation rate in mm\,d$^{-1}$), and the rest, $V_i-V_{below}-e$, is the water in the root zone. The part of that held within the requirement $V_{req}=Z_nS_eS_l$ is \emph{stored}; the excess is deep percolation too. The emitters are not equal, so five emitters at the quantiles $z=-1.28,-0.52,0,0.52,1.28$ of the normal distribution, with discharge $V(1+\sigma_qz)$, are computed and averaged:",
 E(r"E_a=\frac{\overline{V_{st}}}{\overline V},\quad E_s=\frac{\overline{V_{st}}}{V_{req}},\quad DP=\frac{\overline{V_{below}+V_{excess}}}{\overline V},\quad t=\frac{V_{req}}{\bar q\,E_u},",r"$E_a$ is the application efficiency, $E_s$ the storage efficiency, $DP$ the deep-percolation share, $V_{st}$ the volume stored in the root zone of one quantile emitter (L), $V$ the volume it delivers (L), $V_{req}=Z_nS_eS_l$ the requirement per emitter (L, with $Z_n$ in mm and spacings in m), the overbar the average over the five quantiles and $t$ the default run time (h); the factor $E_u$ lengthens the run so that the poorest emitter still refills the root zone.",'eq:d-fate'))
rows=[]
for sid in sorted(TEX):
    s=sh(sid);r=D_(sid);b_=r['b']
    rows.append([sid,SOIL[sid][0],'%.1f'%(s['ks']*24/10),'%.2f'%r['aspect'],'%.1f'%r['t'],'%.0f'%(b_['r']/10*2),'%.0f'%(b_['zb']/10),'%.0f'%(100*r['Ea']),'%.0f'%(100*r['dp']),'%.0f'%(100*r['ev'])])
b+=tabl(['ID','Soil','$K_s$ (cm/d)','$a$','run $t$ (h)','width (cm)','depth (cm)','$E_a$ (\\%)','$DP$ (\\%)','Evap. (\\%)'],rows,'Drip design on the ten soils: inline emitter 2 L/h at 0.5 m, laterals every 1.5 m, buried 25 cm, net depth 9 mm.','llrrrrrrrr')
b+=P(r"The coarse soils give the narrowest and deepest bulbs, and the largest losses to deep percolation; the fine soils spread sideways and hold the water in the root zone. This is why the placement and the emitter spacing must be chosen soil by soil.")
