b+=tabl(['Placement (cm)','run $t$ (h)','bulb depth (cm)','$E_a$ (\\%)','$E_s$ (\\%)','$DP$ (\\%)','Evaporation (\\%)'],rows,'Effect of the depth of placement on the loam S06.','rrrrrrr')
