for Se in (0.2,0.3,0.5,0.75,1.0,1.5):
    r=D_('S06',Se=Se);rows.append(['%.2f'%Se,'%.1f'%r['t'],'%.0f'%(100*r['Ea']),'%.0f'%(100*r['Es']),'%.0f'%(100*r['dp']),'%.0f'%(1e4/(Se*1.5))])
b+=tabl(['Emitter spacing (m)','run $t$ (h)','$E_a$ (\\%)','$E_s$ (\\%)','$DP$ (\\%)','emitters per ha'],rows,'Effect of the emitter spacing on the loam S06 ($S_l=1.5$ m).','rrrrrr')
