b+=tabl(['$q$ (L/h)','$a$','run $t$ (h)','width (cm)','$E_a$ (\\%)','$DP$ (\\%)'],rows,'Effect of the emitter discharge on the loam S06.','rrrrrr')
r=D_('S06')
b+=ex(r"Design a drip system for the loam S06 for a crop that needs $Z_n=9$ mm per irrigation: inline emitters 2 L\,h$^{-1}$ at 0.5 m, laterals 1.5 m apart, 100 m long, 16 mm, 10 m head, buried at 25 cm, root zone 60 cm. Report the run time, the bulb and the fate of the water.",
 r"Requirement per emitter $V_{req}=9\times0.5\times1.5=%.2f$ L \ans $E_u=%.3f$, $\bar q=%.3f$ L\,h$^{-1}$, so $t=V_{req}/(\bar qE_u)=%.2f/(%.3f\times%.3f)=%.2f$ h \ans Volume per emitter $V=\bar qt=%.2f$ L, i.e.\ a gross depth of $%.1f$ mm \ans Aspect ratio of the loam ($K_s=%.1f$ cm\,d$^{-1}$): $a=%.2f$ \ans The average emitter wets a width of $%.0f$ cm to a depth of $%.0f$ cm \ans $E_a=%.1f$, $E_s=%.1f$, $DP=%.1f$, evaporation $%.1f$ per cent \ans Per hectare: $%.0f$ emitters, $%.0f$ m of lateral, system flow $%.2f$ L\,s$^{-1}$\,ha$^{-1}$ \ans"%(r['Vreq'],r['Eu'],r['lat']['qa'],r['Vreq'],r['lat']['qa'],r['Eu'],r['t'],r['V'],r['gross'],sh('S06')['ks']*2.4,r['aspect'],r['b']['r']/10*2,r['b']['zb']/10,100*r['Ea'],100*r['Es'],100*r['dp'],100*r['ev'],1e4/.75,1e4/1.5,1e4/.75*r['lat']['qa']/3600),'A drip design from soil to run time')
